### Place Images on Map with Overlay Component in react-native-maps

Source: https://context7.com/react-native-maps/react-native-maps/llms.txt

The Overlay component allows placing images over specific regions of the map defined by bounds coordinates. It supports both local images (using require) and remote images via URI. Properties like bearing, opacity, and tappable are available, though some are platform-specific (e.g., bearing and opacity for Google Maps, tappable for Android).

```jsx
import React from 'react';
import { StyleSheet } from 'react-native';
import MapView, { Overlay } from 'react-native-maps';

const OverlayExample = () => {
  // Bounds: [southwest, northeast] corners
  const overlayBounds = [
    [37.78, -122.44], // Southwest corner [lat, lng]
    [37.80, -122.42], // Northeast corner [lat, lng]
  ];

  return (
    <MapView
      style={StyleSheet.absoluteFillObject}
      initialRegion={{
        latitude: 37.79,
        longitude: -122.43,
        latitudeDelta: 0.04,
        longitudeDelta: 0.04,
      }}
    >
      {/* Local image overlay */}
      <Overlay
        bounds={overlayBounds}
        image={require('./assets/floor-plan.png')}
        bearing={0} // Rotation in degrees (Google Maps only)
        opacity={0.8} // Google Maps only
        tappable={true} // Android only
        onPress={() => console.log('Overlay pressed')}
      />

      {/* URI-based image overlay */}
      <Overlay
        bounds={[
          [37.76, -122.44],
          [37.78, -122.42],
        ]}
        image={{ uri: 'https://example.com/overlay-image.png' }}
      />
    </MapView>
  );
};

export default OverlayExample;

